def main() -> int:
    for path in (ZIWEI_NLC_12DU_BATCH, ZIWEI_NLC_12DU_EVIDENCE):
        if not path.is_file():
            fail(f"Batch 12DU continuity artifact missing: {path.relative_to(ROOT)}")
